 public static void RepairAndValidate(){EditorSceneManager.OpenScene(Scene);env=UnityEngine.Object.FindAnyObjectByType<EnvironmentPresentation>();game=env.game;var targets=new List<ResearchTarget>();for(int i=0;i<5;i++){var obj=GameObject.Find("Research station "+i);GameObjectUtility.RemoveMonoBehavioursWithMissingScript(obj);var target=obj.GetComponent<ResearchTarget>();if(!target)target=obj.AddComponent<ResearchTarget>();target.stableId="site_"+i;target.displayName=new[]{"Rock sample station","Soil crater sampler","Ridge mineral sensor","Solar inspection","Communications inspection"}[i];targets.Add(target);}env.targets=targets.ToArray();
