 static Mesh LowPolyRibs(GameObject dome,Mesh shell){var vertices=new List<Vector3>();var indices=new List<int>();var edges=new HashSet<string>();var verts=shell.vertices;var tri=shell.triangles;for(int i=0;i<tri.Length;i+=3)for(int edge=0;edge<3;edge++){int a=tri[i+edge],b=tri[i+(edge+1)%3];if(!edges.Add(Math.Min(a,b)+"_"+Math.Max(a,b)))continue;Vector3 p=Vector3.Scale(verts[a]*1.004f,dome.transform.localScale),q=Vector3.Scale(verts[b]*1.004f,dome.transform.localScale);if(Vector3.Distance(p,q)<.02f)continue;Vector3 axis=(q-p).normalized,u=Vector3.Cross(axis,Mathf.Abs(axis.y)<.9f?Vector3.up:Vector3.right).normalized,v=Vector3.Cross(axis,u);int start=vertices.Count;for(int end=0;end<2;end++)for(int j=0;j<6;j++){float angle=j*Mathf.PI/3;vertices.Add((end==0?p:q)+(u*Mathf.Cos(angle)+v*Mathf.Sin(angle))*.023f);}for(int j=0;j<6;j++){int k=(j+1)%6;indices.AddRange(new[]{start+j,start+k,start+j+6,start+k,start+k+6,start+j+6});}}
 var m=new Mesh{name=dome.name+" low-poly structural seams"};m.indexFormat=IndexFormat.UInt32;m.vertices=vertices.ToArray();m.triangles=indices.ToArray();m.RecalculateNormals();m.RecalculateBounds();AssetDatabase.CreateAsset(m,F+"/Models/"+dome.name.Replace(" ","_")+"_Ribs_LowPoly.asset");return m;}

 static void Capture(string name,Camera camera,Vector3? position=null,Vector3? target=null){var old=camera.transform.position;var rot=camera.transform.rotation;if(position.HasValue){camera.transform.position=position.Value;camera.transform.LookAt(target.Value);}var rt=new RenderTexture(1600,900,24);camera.targetTexture=rt;for(int i=0;i<3;i++)camera.Render();RenderTexture.active=rt;var tex=new Texture2D(1600,900,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1600,900),0,0);tex.Apply();File.WriteAllBytes(Out+"/Screenshots/"+name+".png",tex.EncodeToPNG());RenderTexture.active=null;camera.targetTexture=null;UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(tex);camera.transform.SetPositionAndRotation(old,rot);}
