 if(phase>0)System.Threading.Thread.Sleep(10);if(phase>0&&EditorApplication.timeSinceStartup-began>60)throw new Exception("Controlled phase timeout: "+phase);if(phase==1&&game.prototype.elapsed-simBegan>=1){checks.Add("Walking observation: simulation seconds="+(game.prototype.elapsed-simBegan)+" displacement="+Vector3.Distance(before,game.prototype.astronaut.transform.position)+" frame="+Time.frameCount);Check("Astronaut movement",Vector3.Distance(before,game.prototype.astronaut.transform.position)>1);Check("Grounded terrain collision",game.prototype.astronaut.isGrounded);Check("Follow camera live",Vector3.Distance(game.prototype.follow.transform.position,game.prototype.ActivePosition())<10);game.prototype.astronaut.enabled=false;game.prototype.astronaut.transform.position=game.prototype.rover.transform.position+Vector3.right*3;game.prototype.astronaut.enabled=true;Physics.SyncTransforms();Check("Boarding",game.Interact());game.modes.Submit(new NativeInput{movement=Vector2.up,accelerate=true});before=game.prototype.rover.transform.position;began=EditorApplication.timeSinceStartup;simBegan=game.prototype.elapsed;phase=2;}
