 else if(phase==3&&game.prototype.elapsed-simBegan>=1){var wheel=game.prototype.roverVisual.Find("Wheel_-1_0").GetComponent<Renderer>();bool groundRay=Physics.Raycast(wheel.bounds.center+Vector3.up,Vector3.down,out var groundHit,4,1<<0);checks.Add("Measured wheel lower-bound clearance="+(groundRay?(wheel.bounds.min.y-groundHit.point.y).ToString():"unavailable"));Check("Rover wheel ground clearance",groundRay&&Mathf.Abs(wheel.bounds.min.y-groundHit.point.y)<.15f);Check("Added boots preserve character rig",game.prototype.leftLeg.Find("Added EVA boot")&&game.prototype.rightLeg.Find("Added EVA boot"));Check("Safe rover exit",game.Interact());Check("Persistent astronaut",game.prototype.astronaut.gameObject==avatar&&game.prototype.astronaut.enabled);game.Publish();Check("Live rover telemetry",game.telemetry.records.Any(x=>x.id=="rover.battery"));Check("Scan and export",game.Scan()&&File.Exists(game.Export(Out+"/Export")));Check("Local save load",game.Save()&&game.Load());Check("Research range gate",!env.targets[0].TryScan(game));Check("Shaders supported",UnityEngine.Object.FindObjectsByType<Renderer>().All(r=>r.sharedMaterials.All(m=>m&&m.shader&&m.shader.isSupported)));game.prototype.astronaut.enabled=false;var scanPoint=env.targets[0].transform.position+Vector3.right;if(Physics.Raycast(scanPoint+Vector3.up*2,Vector3.down,out var scanGround,6,1<<0))scanPoint=scanGround.point+Vector3.up*.03f;game.prototype.astronaut.transform.position=scanPoint;game.prototype.astronaut.enabled=true;Check("Research proximity scan",env.targets[0].TryScan(game));env.AssociateScans();Check("Research telemetry association",game.telemetry.records.Any(x=>x.id=="research.site_0"));pausedTick=game.tick;pausedOxygen=game.prototype.oxygen;env.SetPaused(true);Check("Pause mode switches safely",env.paused&&!game.enabled&&Time.timeScale==0);began=EditorApplication.timeSinceStartup;phase=4;}else if(phase==4&&EditorApplication.timeSinceStartup-began>1){Check("Paused resource clock stable",game.tick==paus